mapper.select:
select syob.*
from sal_yt_order_sub as syob where is_deleted = 0
and id = #{id}

select syob.*
from sal_yt_order_sub as syob

 is_deleted=0
    and order_id = #{orderId}
    and order_type = #{orderType}
    and shipping_method = #{shippingMethod}
    and order_time = #{orderTime}
    and delivery_time = #{deliveryTime}
    and is_inbound_delivery = #{isInboundDelivery}
    and is_collected_shipping_cost = #{isCollectedShippingCost}

SELECT base.*, -- 利润：base.totalOrderPrice 已经是换算后的值，直接减去成本 (base.totalOrderPrice - base.totalOrderCost) AS profit, -- 利润率：base.totalOrderPrice 已经是换算后的值 CASE WHEN base.totalOrderPrice > 0 THEN ((base.totalOrderPrice - base.totalOrderCost) / base.totalOrderPrice) * 100 ELSE 0 END as profitRate FROM ( SELECT so.id, so.code , so.create_time AS create_time, so.receive_status as receiveStatus, so.currency, so.exchange_rate, -- 运费：当已收取运费时取主表shipping_cost，未收取时从子订单的receive_shipping字段累加 CASE WHEN so.is_collected_shipping_cost = 0 THEN COALESCE(SUM(sos.receive_shipping), 0) ELSE so.shipping_cost END AS totalShippingPrice, -- 优惠金额（从主表） so.discount_amount as discountAmount, so.is_collected_shipping_cost, so.status, -- 商品收入：美元订单需要乘以汇率换算为人民币 CASE WHEN so.currency = '1' THEN SUM(sosi.price * sosi.number) * so.exchange_rate ELSE SUM(sosi.price * sosi.number) END AS totalItemPrice, -- 订单总收入 = 商品收入 + 运费 - 优惠金额：美元订单需要乘以汇率换算为人民币 -- 当未收取运费时，运费从子订单的receive_shipping字段累加 CASE WHEN so.currency = '1' THEN (SUM(sosi.price * sosi.number) + CASE WHEN so.is_collected_shipping_cost = 0 THEN COALESCE(SUM(sos.receive_shipping), 0) ELSE so.shipping_cost END - so.discount_amount) * so.exchange_rate ELSE SUM(sosi.price * sosi.number) + CASE WHEN so.is_collected_shipping_cost = 0 THEN COALESCE(SUM(sos.receive_shipping), 0) ELSE so.shipping_cost END - so.discount_amount END AS totalOrderPrice, SUM(sosi.supplier_price * sosi.number) AS totalItemCost, -- 运费成本：从子订单的payment_shipping字段累加 COALESCE(SUM(sos.payment_shipping), 0) AS totalShippingCost, SUM(sosi.supplier_price * sosi.number) + COALESCE(SUM(sos.payment_shipping), 0) AS totalOrderCost, so.follow_employee_id, so.sale_employee_id, so.follow_ratio, so.sale_ratio, (select nick_name from sys_user where user_id = so.follow_employee_id) as follow_employee_name, (select nick_name from sys_user where user_id = so.sale_employee_id) as sale_employee_name, c.name as customerName FROM sal_yt_order so LEFT JOIN sal_yt_order_sub sos ON so.id = sos.order_id AND sos.is_deleted = 0 LEFT JOIN sal_yt_order_sub_item sosi ON sos.id = sosi.order_sub_id AND sosi.is_deleted = 0 LEFT JOIN sal_yt_customer c ON so.customer_id = c.id AND c.is_deleted = 0 WHERE so.is_deleted = 0
AND so.code LIKE CONCAT('%', #{orderCode}, '%')
AND so.sale_employee_id = #{saleEmployeeId}
AND so.follow_employee_id = #{followEmployeeId}
AND c.name LIKE CONCAT('%', #{customerName}, '%')
AND c.id = #{customerId}
GROUP BY so.id ) AS base WHERE 1=1
AND CASE WHEN base.totalOrderPrice > 0 THEN ((base.totalOrderPrice - base.totalOrderCost) / base.totalOrderPrice) * 100 ELSE 0 END >= #{profitRateMin}
AND CASE WHEN base.totalOrderPrice > 0 THEN ((base.totalOrderPrice - base.totalOrderCost) / base.totalOrderPrice) * 100 ELSE 0 END <= #{profitRateMax}
and base.`status`!=3 order by base.create_time desc

SELECT base.customerIncome, base.customerExpense, base.customerIncome - IFNULL(base.customerExpense, 0) AS customerProfit, CASE WHEN base.customerIncome = 0 THEN 0 ELSE (base.customerIncome - IFNULL(base.customerExpense, 0))/base.customerIncome END AS customerProfitRate, base.customerId, base.customerCode, base.customerName, base.saleEmployeeName FROM ( SELECT -- IFNULL(SUM(syosi.price * syosi.number), 0) + IFNULL(SUM(syosi.base_price * syosi.number), 0) + IFNULL(SUM(CASE WHEN syo.is_collected_shipping_cost = 1 THEN CASE WHEN syo.currency = '1' THEN syo.shipping_cost * syo.exchange_rate ELSE syo.shipping_cost END ELSE syos.receive_shipping_base_price END), 0) - IFNULL(SUM(CASE WHEN syo.currency = '1' THEN syo.discount_amount * syo.exchange_rate ELSE syo.discount_amount END), 0) AS customerIncome, IFNULL(SUM(syosi.supplier_price * syosi.number), 0) + IFNULL(SUM(syos.payment_shipping), 0) AS customerExpense, syo.customer_id as customerId, -- (select nick_name from sys_user where user_id =syo.sale_employee_id) as saleEmployeeName, MAX((select nick_name from sys_user where user_id = syo.sale_employee_id)) as saleEmployeeName, syc.name as customerName, syc.code as customerCode FROM sal_yt_customer as syc left join sal_yt_order AS syo on syo.customer_id = syc.id LEFT JOIN sal_yt_order_sub AS syos ON syo.id = syos.order_id LEFT JOIN sal_yt_order_sub_item AS syosi ON syosi.order_sub_id = syos.id WHERE syo.is_deleted = 0 AND syos.is_deleted = 0 AND syosi.is_deleted = 0
and syc.name like concat('%',#{customerName},'%')
and syc.code like concat('%',#{customerCode},'%')
and syo.create_time >= #{startTime}
and syo.create_time <= #{endTime}
and syo.sale_employee_id = #{saleEmployeeId}
group by syc.id, syc.name, syc.code, syo.customer_id ) AS base WHERE 1=1
AND CASE WHEN base.customerIncome = 0 THEN 0 ELSE (base.customerIncome - IFNULL(base.customerExpense, 0))/base.customerIncome END >= #{profitRateMin}
AND CASE WHEN base.customerIncome = 0 THEN 0 ELSE (base.customerIncome - IFNULL(base.customerExpense, 0))/base.customerIncome END <= #{profitRateMax}

SELECT base.customerIncome, base.customerExpense, base.customerIncome - IFNULL(base.customerExpense, 0) AS customerProfit, CASE WHEN base.customerIncome = 0 THEN 0 ELSE (base.customerIncome - IFNULL(base.customerExpense, 0))/base.customerIncome END AS customerProfitRate, base.customerId, base.customerCode, base.customerName, base.saleEmployeeName, base.customerOrderIncome, base.customerShippingIncome, base.customerOrderExpense, base.customerShippingExpense, base.customerDiscount FROM ( SELECT IFNULL(SUM(syosi.base_price * syosi.number), 0) + IFNULL(SUM(CASE WHEN syo.is_collected_shipping_cost = 1 THEN CASE WHEN syo.currency = '1' THEN syo.shipping_cost * syo.exchange_rate ELSE syo.shipping_cost END ELSE syos.receive_shipping_base_price END), 0) - IFNULL(SUM(CASE WHEN syo.currency = '1' THEN syo.discount_amount * syo.exchange_rate ELSE syo.discount_amount END), 0) AS customerIncome, IFNULL(SUM(syosi.supplier_price * syosi.number), 0) + IFNULL(SUM(syos.payment_shipping), 0) AS customerExpense, syo.customer_id as customerId, (select nick_name from sys_user where user_id =syo.sale_employee_id) as saleEmployeeName, syc.name as customerName, syc.code as customerCode, SUM(syosi.base_price * syosi.number) as customerOrderIncome, SUM(CASE WHEN syo.is_collected_shipping_cost = 1 THEN CASE WHEN syo.currency = '1' THEN syo.shipping_cost * syo.exchange_rate ELSE syo.shipping_cost END ELSE syos.receive_shipping_base_price END) as customerShippingIncome, SUM(syosi.supplier_price * syosi.number) as customerOrderExpense, SUM(syos.payment_shipping) as customerShippingExpense, SUM(CASE WHEN syo.currency = '1' THEN syo.discount_amount * syo.exchange_rate ELSE syo.discount_amount END) as customerDiscount FROM sal_yt_customer as syc left join sal_yt_order AS syo on syo.customer_id = syc.id LEFT JOIN sal_yt_order_sub AS syos ON syo.id = syos.order_id LEFT JOIN sal_yt_order_sub_item AS syosi ON syosi.order_sub_id = syos.id WHERE syo.is_deleted = 0 AND syos.is_deleted = 0 AND syosi.is_deleted = 0 And syc.id= #{customerId}
and syc.name like concat('%',#{customerName},'%')
and syc.code like concat('%',#{customerCode},'%')
and syo.create_time >= #{startTime}
and syo.create_time <= #{endTime}
and syo.sale_employee_id = #{saleEmployeeId}
GROUP BY syc.id, syo.customer_id, syo.sale_employee_id ) AS base

SELECT base.categoryName, base.orderNumber, CASE WHEN base.customerOrderIncome = 0 THEN 0 ELSE (base.customerOrderIncome - base.customerOrderExpense)/base.customerOrderIncome END AS profitRate, (base.customerOrderIncome - base.customerOrderExpense) as profit, base.categoryId FROM ( SELECT (select name from pro_yt_product_category where id = pyp.category_id) as categoryName, pyp.category_id as categoryId, sum(syosi.number) as orderNumber, SUM(syosi.price * syosi.number) as customerOrderIncome, SUM(syosi.supplier_price * syosi.number) as customerOrderExpense FROM sal_yt_customer as syc left join sal_yt_order AS syo on syo.customer_id = syc.id LEFT JOIN sal_yt_order_sub AS syos ON syo.id = syos.order_id LEFT JOIN sal_yt_order_sub_item AS syosi ON syosi.order_sub_id = syos.id left join pro_yt_product as pyp on pyp.id = syosi.product_id WHERE syo.is_deleted = 0 AND syos.is_deleted = 0 AND syosi.is_deleted = 0 And syc.id= #{customerId}
and syc.name like concat('%',#{customerName},'%')
and syc.code like concat('%',#{customerCode},'%')
and syo.create_time >= #{startTime}
and syo.create_time <= #{endTime}
and syo.sale_employee_id = #{saleEmployeeId}
group by pyp.category_id ) AS base

SELECT (base.customerOrderIncome - base.customerOrderExpense) as profit FROM ( SELECT SUM(syosi.price * syosi.number) as customerOrderIncome, SUM(syosi.supplier_price * syosi.number) as customerOrderExpense FROM sal_yt_customer as syc left join sal_yt_order AS syo on syo.customer_id = syc.id LEFT JOIN sal_yt_order_sub AS syos ON syo.id = syos.order_id LEFT JOIN sal_yt_order_sub_item AS syosi ON syosi.order_sub_id = syos.id left join pro_yt_product as pyp on pyp.id = syosi.product_id WHERE syo.is_deleted = 0 AND syos.is_deleted = 0 AND syosi.is_deleted = 0 And syc.id= #{customerId}
and syc.name like concat('%',#{customerName},'%')
and syc.code like concat('%',#{customerCode},'%')
and syo.create_time >= #{startTime}
and syo.create_time <= #{endTime}
and syo.sale_employee_id = #{saleEmployeeId}
) AS base

select a.*
from sal_yt_order_sub_item a left join sal_yt_order_sub b on a.order_sub_id=b.id
where b.order_id = #{orderId}
  and a.is_deleted = 0 and b.is_deleted=0
 and a.order_sub_id != #{orderSubId}

select *
from sal_yt_order_sub
where order_id = #{orderId}
and id != #{orderSubId}
and is_deleted = 0
